custom_css:
/* --- 午夜情歌 像素风万圣节哥特 感谢代码楼里老师们的代码https://discord.com/channels/1291925535324110879/1380392618336194702
感谢尾老师，类名，输入框伪提示词来自尾老师，hy老师的去除思维链箭头，na老师的悬浮底栏和思维链文字自定义，楼层信息自定义，12老师的去思维链背景色。感谢NA老师的去阴影，感谢咩野老师的去除全局阴影. --- */

/* --- 1. 字体导入 --- */
@import url('https://fonts.googleapis.com/css2?family=VT323&display=swap');
@import url('https://fonts.googleapis.com/css2?family=Yusei+Magic&display=swap');
@import url("https://fontsapi.zeoseven.com/292/main/result.css");
@import url("https://fontsapi.zeoseven.com/45/main/result.css");
@import url("https://fontsapi.zeoseven.com/521/main/result.css");
@import url("https://fontsapi.zeoseven.com/811/main/result.css");

/* --- 2. 核心颜色与样式变量 --- */
:root {
    --theme-bg: #050000;
    --panel-bg-color: rgba(20, 5, 5, 0.85);
    --panel-bg-hover: rgba(40, 10, 10, 0.95);
    --card-bg: rgba(15, 0, 0, 0.85);
    --input-bg: rgba(20, 5, 5, 0.9);
    --text-main: #e2e8f0;
    --text-subtle: #ffb3b3;
    --accent-red: #e60000;
    --accent-darkred: #800000;
    --accent-white: #ffffff;
    --font-pixel: 'VT323', monospace;
    --font-cute: 'Yusei Magic', sans-serif;
    --font-main: "LXGW WenKai", var(--font-pixel);
    --font-quote: "JetBrains Maple Mono", var(--font-pixel);
    --font-code: "nzgrRuYinZouZhangKai", monospace;
    --font-title: "ChangBanDianSong 16 SC", var(--font-pixel);
}

/* --- 3. 全局样式与像素化设定 --- */
* { box-shadow: none !important; border-style: none !important; }
body { 
    background-color: var(--theme-bg) !important; 
    background-image: linear-gradient(rgba(5, 0, 0, 0.8), rgba(20, 0, 5, 0.9));
    background-size: cover; background-position: center; background-attachment: fixed;
    color: var(--text-main); font-family: var(--font-main); font-weight: normal; 
}
/* 全局悬浮小物粒子 */
body::after {
    content: ''; position: fixed; top: 10%; left: 5%; width: 150px; height: 150px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/JGTk/2048X2048/2026-04-29_130721.png/webp');
    background-size: contain; background-repeat: no-repeat; opacity: 0.8;
    pointer-events: none; z-index: 9999;
    animation: pixel-float 6s infinite alternate steps(10);
}
@keyframes pixel-float { 0% { transform: translateY(0) scale(1) rotate(-5deg); } 100% { transform: translateY(-20px) scale(1.05) rotate(5deg); } }

#sheld, #character_view { background: transparent !important; margin: 0 auto !important; left: 0; right: 0; border: none !important; overflow: visible !important; }
#chat { background: transparent !important; align-items: center !important; padding-bottom: 180px !important; }

/* 仅作用于正文的一二级标题，避免吞掉icon */
.mes_text h1, .mes_text h2, .mes_text h3, .mes_text h4 { font-family: var(--font-title); color: var(--accent-red); font-weight: normal; text-shadow: 2px 2px 0px var(--accent-darkred); }
.standoutHeader, .inline-drawer-header, .title_restorable { font-family: var(--font-cute); color: var(--accent-red); font-weight: normal; }

/* --- 4. 顶部导航栏 --- */
#top-settings-holder { position:relative; background-color: var(--panel-bg-color); backdrop-filter: blur(8px); border-bottom: 2px solid var(--accent-darkred) !important; }
.drawer-icon.fa-fw::before { content: '' !important; font-size: 0 !important; }
.drawer-icon.fa-fw { width: 35px; height: 40px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: all 0.2s steps(3); image-rendering: pixelated; }
.drawer-icon.fa-fw:hover { transform: translateY(-4px); filter: drop-shadow(0 4px 0px var(--accent-red)); }

.drawer-icon.fa-sliders, #ai-config-button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/9LpW/2048X2048/2026-04-29_130728.png/webp'); }
.drawer-icon.fa-plug, #sys-settings-button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/3Snm/2048X2048/2026-04-29_130738.png/webp'); }
.drawer-icon.fa-font, #advanced-formatting-button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/9LpW/2048X2048/2026-04-29_130728.png/webp'); }
.drawer-icon.fa-book-atlas, #WI-SP-button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/3Snm/2048X2048/2026-04-29_130738.png/webp'); }
.drawer-icon.fa-user, #user-settings-button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/9LpW/2048X2048/2026-04-29_130728.png/webp'); }
.drawer-icon.fa-image, .drawer-icon.fa-panorama { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/3Snm/2048X2048/2026-04-29_130738.png/webp'); }
.drawer-icon.fa-cubes, #extensions-settings-button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/9LpW/2048X2048/2026-04-29_130728.png/webp'); }
.drawer-icon.fa-bars-progress, #table_database_settings_drawer .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/3Snm/2048X2048/2026-04-29_130738.png/webp'); }
.drawer-icon.fa-face-smile, #persona-management-button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/9LpW/2048X2048/2026-04-29_130728.png/webp'); }
.drawer-icon.fa-address-card, #character_popup_button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/3Snm/2048X2048/2026-04-29_130738.png/webp'); }

/* 抽屉与弹窗背景图 */
.drawer-content, dialog.popup .popup-body, #dialogue_popup {
    background-image: linear-gradient(rgba(10, 0, 5, 0.8), rgba(20, 5, 10, 0.9)), url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/Nx3B/1232X928/metro.ant_Retro_pixel_art_game_screenshot_richly_detailed_sta_f5c57601-70a3-4d6f-8a09-a5dc1b40b581_3.png/webp') !important;
    background-size: cover; background-position: center;
    border: none !important; border-radius: 0;
}

/* --- 5. 底部悬浮输入栏 --- */
#send_textarea::placeholder { color: transparent !important; opacity: 0 !important; }
#form_sheld { position: absolute !important; bottom: 25px !important; left: 0; right: 0; display: flex; justify-content: center; z-index: 1000; pointer-events: none; overflow: visible !important; }
#send_form { 
    pointer-events: auto; width: 80% !important; max-width: 800px !important; margin: 0 auto !important; 
    background-color: var(--input-bg) !important; padding: 10px 15px !important; 
    backdrop-filter: blur(10px) !important; position: relative; 
    border: 4px double var(--accent-red) !important;
    border-radius: 0 !important;
    animation: form-float-anim 3s infinite alternate steps(4);
}
@keyframes form-float-anim { 0% { transform: translateY(0); } 100% { transform: translateY(-6px); } }
#send_form:hover { background-color: var(--panel-bg-hover) !important; }
#send_textarea { clip-path: none !important; border: none !important; background: transparent !important; color: var(--text-main) !important; }

/* 输入框右上角贴图 */
#send_form::before {
    content: ''; position: absolute; top: -35px; right: -15px; width: 60px; height: 60px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/MCl1/2048X2048/2026-04-29_130708.png/webp');
    background-size: contain; background-repeat: no-repeat; z-index: 50; pointer-events: none;
    animation: bat-float 2s infinite alternate ease-in-out;
}
@keyframes bat-float { 0% { transform: translateY(0) rotate(-5deg); } 100% { transform: translateY(-5px) rotate(5deg); } }

/* 伪提示词 */
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before { 
    content: '永遠の夜が君を待っている... (真夜中の囁き)'; 
    color: var(--accent-red); position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); 
    font-family: var(--font-cute); font-size: clamp(11px, 2vw, 16px); pointer-events: none; z-index: 10; 
    white-space: nowrap; letter-spacing: 1px; 
    opacity: 0.7; animation: pixel-blink 1.5s infinite steps(2);
}
@keyframes pixel-blink { 0% { opacity: 0.2; } 100% { opacity: 1; } }

#options_button::before, #send_but::before, #send_form #extensionsMenuButton::before, #ai_retry_button::before, #auto_completion_button::before { display: none !important; }
#options_button, #send_but, #send_form #extensionsMenuButton, #ai_retry_button, #auto_completion_button { width: 34px; height: 34px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: all 0.2s steps(2); font-size: 0; border: none; background-color: transparent; image-rendering: pixelated; margin: 0 2px; }
#options_button:hover, #send_but:hover, #send_form #extensionsMenuButton:hover, #ai_retry_button:hover, #auto_completion_button:hover { transform: translateY(-3px) scale(1.1); filter: drop-shadow(0 0 5px var(--accent-red)); }

#options_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/dx7V/2048X2048/2026-04-29_130816.png/webp'); }
#send_form #extensionsMenuButton { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/mSFz/2048X2048/2026-04-29_130452.png/webp'); }
#send_but { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/1WAY/2048X2048/2026-04-29_130748.png/webp'); }
#ai_retry_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/dx7V/2048X2048/2026-04-29_130816.png/webp'); filter: hue-rotate(180deg); }
#auto_completion_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/mSFz/2048X2048/2026-04-29_130452.png/webp'); filter: hue-rotate(90deg); }

/* --- 6. 核心：消息卡片 --- */
.mes { 
    display: flex; flex-direction: column; 
    padding: 0 !important; margin: 100px auto 60px !important; 
    width: 85%; max-width: 800px; 
    border: none !important; border-radius: 0 !important;
    backdrop-filter: blur(5px) !important; overflow: visible !important; position: relative; 
}
.mes[is_user="false"] { background: var(--card-bg) !important; }
.mes[is_user="true"] { background: rgba(25, 0, 5, 0.85) !important; }

/* 左下角小幽灵承接框 */
.mes::after {
    content: '';
    position: absolute;
    bottom: -30px;
    left: 0px;
    width: 140px;
    height: 35px;
    background: 
        url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/0McY/2048X2048/2026-04-29_131330.png/webp') 5px center / 25px no-repeat,
        url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/tbfB/2048X2048/2026-04-29_131406.png/webp') 45px center / 25px no-repeat,
        url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/0McY/2048X2048/2026-04-29_131330.png/webp') 85px center / 25px no-repeat;
    background-color: rgba(10, 0, 0, 0.7);
    border: 1px solid var(--accent-darkred);
    z-index: 20;
    pointer-events: none;
    animation: ghost-float 3s infinite alternate ease-in-out;
}
@keyframes ghost-float { 0% { transform: translateY(0); } 100% { transform: translateY(-4px); } }

/* 消息框顶部背景包装器 */
.mes .mesAvatarWrapper {
    display: flex; justify-content: center; align-items: center; padding: 0;
    width: 100%; height: 130px !important; min-height: 130px !important;
    background-size: cover; background-position: center; background-repeat: no-repeat;
    position: relative; z-index: 5; overflow: visible !important;
    border-bottom: 2px solid var(--accent-darkred);
}
.mes[is_user="false"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/PfgJ/1232X928/pixel-large-mosaic-1777440339350.png/webp'); }
.mes[is_user="true"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/mbU9/1232X928/pixel-large-mosaic-1777440194717.png/webp'); }

/* --- 楼层 ID（独立悬浮于顶部外侧） --- */
.mesIDDisplay {
    position: absolute !important; top: -45px !important; 
    background: #050000 !important; border: 1px solid var(--accent-darkred) !important;
    color: var(--accent-red) !important; font-size: 13px !important; z-index: 100; 
    padding: 6px 12px !important; white-space: nowrap; line-height: 1 !important; border-radius: 0 !important;
    font-family: var(--font-pixel) !important;
}
.mes[is_user="false"] .mesIDDisplay { right: 0px !important; left: auto !important; transform: none !important; }
.mes[is_user="true"] .mesIDDisplay { left: 0px !important; right: auto !important; transform: none !important; }
.mesIDDisplay::before { content: '第 '; color: var(--text-subtle); }
.mesIDDisplay::after { content: ' 幕'; color: var(--text-subtle); }

/* --- 时间戳（独立悬浮于顶部中央） --- */
.mes .timestamp {
    position: absolute !important; 
    top: -45px !important; /* 从底部移到顶部, 与姓名/楼层垂直对齐 */
    left: 50% !important; /* 水平居中 */
    transform: translateX(-50%) !important; /* 精准水平居中 */
    bottom: auto !important;
    right: auto !important;
    background: #050000 !important; 
    border: 1px solid var(--accent-darkred) !important;
    color: var(--accent-red) !important; 
    font-size: 13px !important; 
    z-index: 99; /* z-index略低，避免覆盖其他元素 */
    padding: 6px 12px !important; 
    white-space: nowrap; 
    line-height: 1 !important; 
    border-radius: 0 !important;
    font-family: var(--font-pixel) !important;
}
/* 强制覆写内部小字体的样式 */
.mes .timestamp small, .mes .mes_timer .timestamp, small.timestamp {
    font-size: 13px !important; 
    font-family: var(--font-pixel) !important; 
    color: var(--accent-red) !important;
}

/* --- 重构头像框（脱离边缘，独立悬浮于侧边） --- */
.mes .avatar {
    position: absolute; top: 20px; width: 90px; height: 90px; 
    background: #050000 !important; 
    padding: 3px !important; 
    border: 2px solid var(--accent-red) !important;
    z-index: 130; display: flex !important; align-items: center; justify-content: center;
    border-radius: 0 !important; box-shadow: 4px 4px 0px rgba(128, 0, 0, 0.6) !important;
}
.mes[is_user="false"] .avatar { left: -45px; }
.mes[is_user="true"] .avatar { right: -45px; left: auto; }
.mes .avatar img { width: 100% !important; height: 100% !important; object-fit: cover !important; border-radius: 0 !important; border: none !important; image-rendering: pixelated; }

/* 正文区域 */
.mes .mes_block { background-color: transparent !important; background-image: none !important; padding: 25px 25px 35px 25px !important; position: relative; border: none !important; overflow: visible !important; min-height: 80px !important; z-index: 10; }
.mes .mes_text, .mes_reasoning { background: transparent !important; border: none !important; padding: 0 !important; margin: 0 !important; backdrop-filter: none !important; }

.mes .mes_block > .ch_name { 
    display: flex !important; position: absolute; 
    top: -80px !important; /* <<< 问题就出在这行 */
    width: auto !important; height: auto !important;
    background: rgba(10, 0, 0, 0.9) !important; 
    border: 2px solid var(--accent-red) !important; 
    padding: 6px 16px !important; 
    z-index: 120; 
    box-shadow: 4px 4px 0px rgba(128, 0, 0, 0.5) !important; 
    flex-direction: column;
}
/* AI姓名居左，与右侧楼层信息形成对立 */
.mes[is_user="false"] .mes_block > .ch_name { left: 0px !important; right: auto !important; align-items: flex-start !important; }
/* User姓名居右，与左侧楼层信息形成对立 */
.mes[is_user="true"] .mes_block > .ch_name { right: 0px !important; left: auto !important; align-items: flex-end !important; }
.mes .ch_name > .flex-container { display: flex !important; align-items: center !important; gap: 10px !important; flex-wrap: nowrap !important; }
.mes .ch_name .name_text { 
    font-family: var(--font-cute) !important; font-size: 18px !important; 
    color: var(--accent-white) !important; text-shadow: 2px 2px 0px var(--accent-darkred); 
    background: transparent !important; padding: 0 !important; border: none !important; line-height: 1;
}

.mes[is_user="false"] .ch_name::after {
    content: '「...血の匂いがする...」';
    display: block; font-size: 12px; color: var(--accent-darkred); margin-top: 4px; font-family: var(--font-cute);
}
.mes[is_user="true"] .ch_name::after {
    content: '「...逃げられない運命...」';
    display: block; font-size: 12px; color: var(--accent-darkred); margin-top: 4px; font-family: var(--font-cute);
}

/* --- 思维链日系自定义 --- */
#chat .mes .mes_reasoning_header { background: transparent !important; border: none !important; border-radius: 0; backdrop-filter: none !important; padding: 0 !important; margin-bottom: 12px !important; display: inline-flex !important; align-items: center !important; }
.mes_reasoning_arrow { display: none !important; }
.mes_reasoning_header h4, .mes_reasoning_header_title { font-size: 0 !important; visibility: hidden; }
.mes_reasoning_header h4::before, .mes_reasoning_header_title::before { 
    content: "🦇 闇の深淵で思考中 [Darkness Loading]..."; 
    font-family: var(--font-cute); font-size: 13px !important; 
    color: var(--accent-red); visibility: visible; letter-spacing: 1px; 
    text-shadow: 1px 1px 0px #000;
}
.mes_reasoning { border-left: 4px solid var(--accent-darkred) !important; padding-left: 15px !important; margin-bottom: 20px !important; color: var(--text-subtle); font-family: var(--font-quote); font-size: 0.95em; }
.mes .mes_text { line-height: 1.8; color: var(--text-main); font-size: 16px; text-align: justify; }

/* --- 排版与文字特效 --- */
.mes_text h1 { font-family: var(--font-title); color: var(--accent-red); font-size: 1.8em; text-align: center; position: relative; padding-bottom: 10px; margin: 25px 0 15px 0; border-bottom: 2px dashed var(--accent-darkred) !important; font-weight: normal; }
.mes_text h1::before { content: '【 '; color: var(--accent-darkred); } .mes_text h1::after { content: ' 】'; color: var(--accent-darkred); }
.mes_text h2 { font-family: var(--font-title); color: var(--accent-red); font-size: 1.5em; padding: 4px 0 4px 15px; border-left: 6px solid var(--accent-darkred) !important; margin: 20px 0 10px 0; background: linear-gradient(to right, rgba(128, 0, 0, 0.2) 0%, transparent 100%); font-weight: normal; }
.mes_text em, .mes_text i { font-family: var(--font-quote); font-style: normal !important; color: var(--text-subtle); background: rgba(128, 0, 0, 0.15); padding: 2px 4px; border: 1px dashed var(--accent-darkred); }
.mes_text strong, .mes_text b { font-family: var(--font-main); color: var(--accent-white); font-weight: bold; text-shadow: 1px 1px 2px var(--accent-red); }
.mes_text blockquote { background-color: rgba(10, 0, 0, 0.6); border: none !important; border-left: 6px solid var(--accent-red) !important; padding: 12px 18px; margin: 15px 0; font-family: var(--font-quote); color: var(--quote_text_color); }
.mes_text span.quote, .mes_text q, .mes_text .dialogue { font-family: var(--font-quote); color: var(--quote_text_color); }
.mes_text code { font-family: var(--font-code) !important; background-color: rgba(0, 0, 0, 0.8) !important; color: var(--accent-red) !important; padding: 4px 8px; border: 1px solid var(--accent-darkred) !important; }

/* --- 编辑与互动按钮 --- */
.mes .mes_buttons, .mes .mes_edit_buttons { flex-direction: row-reverse; gap: 6px; position: static !important; opacity: 0.3; transition: opacity 0.2s steps(2); pointer-events: auto !important; }
.mes:hover .mes_buttons, .mes:hover .mes_edit_buttons { opacity: 1; }
.mes .mes_buttons .mes_button, .mes .mes_edit_buttons .mes_button {
    background-color: var(--card-bg) !important; padding: 0 !important; cursor: pointer; height: 28px !important; width: 28px !important; border: 1px solid var(--accent-darkred) !important; border-radius: 0 !important; background-size: 75% !important; background-repeat: no-repeat !important; background-position: center !important; image-rendering: pixelated; transition: all 0.2s steps(2); font-family: "Font Awesome 6 Free", "FontAwesome" !important; font-weight: 900 !important; font-size: 13px !important; color: var(--text-main) !important; display: inline-flex !important; align-items: center !important; justify-content: center !important; -webkit-font-smoothing: antialiased !important;
}
.mes .mes_buttons .mes_button:hover, .mes .mes_edit_buttons .mes_button:hover { background-color: var(--accent-darkred) !important; transform: scale(1.1) translateY(-2px); }

/* --- 全局UI设定 --- */
.standoutHeader, .inline-drawer-header, .title_restorable, #extensions_settings2 > div, #extensions_settings > div, .openai_logit_bias_preset_form, details > summary, div[name*='Toggles'] h4 { background: var(--card-bg) !important; border: none !important; border-radius: 0 !important; padding: 10px 15px !important; margin-bottom: 8px !important; color: var(--accent-red) !important; font-family: var(--font-pixel); border-bottom: 1px solid var(--accent-darkred) !important; }
input[type="text"], input[type="number"], input[type="search"], textarea, select, .text_pole { background-color: #000 !important; border: 1px solid var(--accent-darkred) !important; color: var(--accent-white) !important; border-radius: 0 !important; padding: 6px !important; font-family: var(--font-pixel); }
input:focus, textarea:focus, select:focus { outline: none !important; border: 1px solid var(--accent-red) !important; background-color: #1a0000 !important; }
.menu_button { background-color: var(--card-bg) !important; border: 1px solid var(--accent-darkred) !important; color: var(--text-main) !important; transition: all 0.2s steps(2); border-radius: 0 !important; font-family: var(--font-pixel); }
.menu_button:hover { background-color: var(--accent-darkred) !important; color: white !important; }
input[type="checkbox"]:checked::before { box-shadow: inset 1em 1em var(--accent-red) !important; }

dialog.popup { background-color: transparent !important; border: none !important; }
dialog.popup .popup-body::before, #dialogue_popup::before { content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0; background-color: rgba(5, 0, 0, 0.85); z-index: 0; }
dialog.popup .popup-body > *, #dialogue_popup > * { position: relative; z-index: 1; }
.menu_button.active, .menu_button.world_set, .menu_button.fav_on, #left-nav-panel .menu_button.selected { background-color: var(--accent-darkred) !important; color: #fff !important; border-color: var(--accent-red) !important; }

input[type="range"]::-webkit-slider-thumb, input[type="range"]::-moz-range-thumb { -webkit-appearance: none !important; appearance: none !important; width: 16px !important; height: 16px !important; background: var(--accent-red) !important; border: 1px solid var(--accent-white) !important; cursor: pointer !important; border-radius: 0 !important; }
.neo-range-slider { background: var(--accent-darkred) !important; border: 1px solid #000; }

/* 打字提示器 */
#typing_indicator { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/JGTk/2048X2048/2026-04-29_130721.png/webp') !important; background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; animation: pixel-bounce 0.8s infinite alternate steps(2); border: none !important; height: 50px !important; width: 50px !important; margin: 10px auto !important; image-rendering: pixelated; }
#typing_indicator .dot { display: none !important; }

/* --- 手机端适配 --- */
@media (max-width: 768px) {
    #send_form { width: 70% !important; }
    #send_form::before { top: -25px; right: -10px; width: 40px; height: 40px; }
    #options_button, #send_but, #send_form #extensionsMenuButton, #ai_retry_button, #auto_completion_button { width: 28px !important; height: 28px !important; min-width: 28px !important; margin: 0 1px !important; }
    .mes { width: 90%; margin-top: 100px !important; margin-bottom: 50px !important; }
    .mes .mesIDDisplay { font-size: 10px !important; left: auto !important; right: 0px !important; top: -35px !important; padding: 4px 8px !important; }
    .mes[is_user="true"] .mesIDDisplay { left: 0px !important; right: auto !important; }
    .mes .mes_timer { font-size: 10px !important; bottom: -30px !important; right: 0px !important; padding: 4px 8px !important; top: auto !important; }
    .mes[is_user="false"] .avatar { left: -15px; width: 60px; height: 60px; top: 20px; }
    .mes[is_user="true"] .avatar { right: -15px; width: 60px; height: 60px; top: 20px; }
    .mes .mesAvatarWrapper { height: 200px !important; min-height: 100px !important; }
    .mes .mes_block { padding: 15px 15px 25px 15px !important; }
    .mes .mes_block > .ch_name { top: -100px !important; padding: 4px 10px !important; } 
    .mes .ch_name .name_text { font-size: 14px !important; }
}

#dialogue_del_mes_ok, #dialogue_del_mes_cancel { display: inline-block !important; visibility: visible !important; opacity: 1 !important; pointer-events: auto !important; position: relative !important; z-index: 10001 !important; background-color: var(--card-bg) !important; color: var(--accent-white) !important; border: 1px solid var(--accent-red) !important; border-radius: 0 !important; padding: 8px 16px !important; margin: 10px 5px !important; cursor: pointer !important; font-family: var(--font-pixel) !important; font-size: 14px !important; }
#dialogue_del_mes_ok:hover { background-color: var(--accent-darkred) !important; }
#dialogue_del_mes_cancel:hover { background-color: #330000 !important; border-color: #660000 !important; }
